INSERT INTO farm (merchant_id, name, type, district, address, business_hours, intro, cover_image, avg_price, rating, traffic_guide, status) VALUES
(1, '盘山红富士苹果园', '果园', '蓟州区', '蓟州区官庄镇盘山景区东门北行2公里', '08:00-16:30', '盘山红富士苹果园坐落于天津蓟州区，远离市区喧嚣，空气清新。园区坚持绿色种植理念，不使用高毒农药，采用物理防虫与有机肥栽培，果品口感纯正、甜度高。园内设有休息区与农家餐饮，适合亲子出游、朋友聚会，欢迎预约采摘。', '/api/file/placeholder/farm1.png', 68, 4.8, '自驾：长深高速汉沽出口下，沿汉北路行驶5公里；公交：公交455路茶淀镇站下车。', 1),
(1, '盘山磨盘柿采摘园', '果园', '蓟州区', '蓟州区官庄镇玉石庄村盘山南麓', '09:00-17:30', '盘山磨盘柿采摘园地处蓟州区生态涵养区，水土条件优越。农场主深耕本地特色品种二十余年，产品质量有口皆碑。除采摘外，还提供农产品加工体验（磨米、酿醋、晒干），让您感受从田间到餐桌的完整过程。', '/api/file/placeholder/farm2.png', 45, 4.7, '自驾：长深高速汉沽出口下，沿汉北路行驶5公里；公交：公交455路茶淀镇站下车。', 1),
