INSERT INTO notice (title, content, publish_time, status) VALUES
('平台试运营公告', '天津地方农特产推广服务平台于2026年9月正式上线试运营。平台首批入驻本地优质农户与农园30余家，覆盖蓟州、西青、静海、宁河等涉农区县。试运营期间全场满88元包邮，欢迎体验！', '2026-09-01 10:00:00', 1),
('金秋采摘季活动通知', '9月至11月为天津地区苹果、柿子、冬枣最佳采摘期。平台农园体验模块已上线"金秋采摘季"专题，预约任意农园即可获赠农家自种蔬菜一份（到园领取）。', '2026-08-25 10:00:00', 1),
('国庆假期预约提示', '国庆假期（10月1日至7日）为采摘高峰期，各农园场次库存有限，建议提前3天以上预约。到园后请向商家出示预留手机号以便现场确认。', '2026-08-15 10:00:00', 1);
